package com.example.appointment.appointment; import java.time.*; import java.util.*; import javax.persistence.LockModeType; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface AppointmentRepository extends JpaRepository<Appointment,Long>{Page<Appointment> findByCustomerId(Long id,Pageable p); @Query("select a from Appointment a where a.staff.id=:s and a.appointmentDate=:d and a.status not in ('CANCELLED','NO_SHOW') and a.startTime<:end and a.endTime>:start") List<Appointment> overlaps(@Param("s")Long s,@Param("d")LocalDate d,@Param("start")LocalTime start,@Param("end")LocalTime end); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select s from StaffProfile s where s.id=:id") Optional<com.example.appointment.staff.StaffProfile> lockStaff(@Param("id")Long id); List<Appointment> findByAppointmentDateBetween(LocalDate a,LocalDate b); List<Appointment> findByStatusAndAppointmentDateBetween(AppointmentStatus s,LocalDate a,LocalDate b);}
